88	// Verifies that the content is exactly one PEM certificate block surrounded
89	// by nothing but whitespace, and that the base64 payload is the given DER.
90	bool validate_single_pem(std::string_view content,
91	                         const std::vector<unsigned char>& der) {
92	    enum class State { BeforeMarker, InBody, AfterMarker };
93	    State state = State::BeforeMarker;
94	    std::string base64;
95	    size_t start = 0;
96	    while (true) {
97	        size_t newline = content.find('\n', start);
98	        std::string_view line = content.substr(
99	            start, newline == std::string_view::npos ? std::string_view::npos
100	                                                     : newline - start);
101	        if (!line.empty() && line.back() == '\r') line.remove_suffix(1);
102	        size_t begin = 0;
103	        size_t end = line.size();
104	        while (begin < end &&
105	               std::isspace(static_cast<unsigned char>(line[begin]))) {
106	            ++begin;
107	        }
108	        while (end > begin &&
109	               std::isspace(static_cast<unsigned char>(line[end - 1]))) {
110	            --end;
111	        }
112	        std::string_view trimmed = line.substr(begin, end - begin);
113	
114	        switch (state) {
115	            case State::BeforeMarker:
116	                if (!trimmed.empty()) {
117	                    if (trimmed != kPemBegin) return false;
118	                    state = State::InBody;
119	                }
120	                break;
121	            case State::InBody:
122	                if (trimmed == kPemEnd) {
123	                    state = State::AfterMarker;
124	                } else if (!trimmed.empty()) {
125	                    for (char c : trimmed) {
126	                        if (!is_base64_token(c)) return false;
127	                    }
128	                    base64.append(trimmed);
129	                }
130	                break;
131	            case State::AfterMarker:
132	                if (!trimmed.empty()) return false;
133	                break;
134	        }
135	
136	        if (newline == std::string_view::npos) break;
137	        start = newline + 1;
138	    }
139	    if (state != State::AfterMarker) return false;
140	
141	    std::vector<unsigned char> decoded;
142	    return base64_decode(base64, decoded) && decoded == der;
143	}
