198	std::string escape_dn_value(const std::string& value) {
199	    std::string out;
200	    for (size_t i = 0; i < value.size(); ++i) {
201	        unsigned char c = static_cast<unsigned char>(value[i]);
202	        if (c == ',' || c == '+' || c == '=' || c == '"' || c == '\\' ||
203	            c == '<' || c == '>' || c == '#' || c == ';') {
204	            out.push_back('\\');
205	            out.push_back(static_cast<char>(c));
206	        } else if (c == ' ' && (i == 0 || i + 1 == value.size())) {
207	            out.append("\\ ");
208	        } else if (c < 0x20) {
209	            char buf[5];
210	            std::snprintf(buf, sizeof(buf), "\\%02X", c);
211	            out.append(buf);
212	        } else {
213	            out.push_back(static_cast<char>(c));
214	        }
215	    }
216	    return out;
217	}
