219	bool format_name(X509_NAME* name, std::string& out) {
220	    int count = X509_NAME_entry_count(name);
221	    int previous_set = -1;
222	    for (int i = 0; i < count; ++i) {
223	        X509_NAME_ENTRY* entry = X509_NAME_get_entry(name, i);
224	        if (entry == nullptr) return false;
225	        ASN1_OBJECT* object = X509_NAME_ENTRY_get_object(entry);
226	        ASN1_STRING* asn1_value = X509_NAME_ENTRY_get_data(entry);
227	        if (object == nullptr || asn1_value == nullptr) return false;
228	
229	        const char* short_name = nullptr;
230	        char oid_buffer[80];
231	        int nid = OBJ_obj2nid(object);
232	        if (nid != NID_undef) short_name = OBJ_nid2sn(nid);
233	        if (short_name == nullptr) {
234	            if (OBJ_obj2txt(oid_buffer, sizeof(oid_buffer), object, 1) <= 0) {
235	                return false;
236	            }
237	            short_name = oid_buffer;
238	        }
239	
240	        unsigned char* utf8_raw = nullptr;
241	        int utf8_length = ASN1_STRING_to_UTF8(&utf8_raw, asn1_value);
242	        if (utf8_length < 0) return false;
243	        std::unique_ptr<unsigned char, OpenSSLFree> utf8_guard(
244	            utf8_raw, OpenSSLFree{});
245	        std::string value(reinterpret_cast<char*>(utf8_raw),
246	                          static_cast<size_t>(utf8_length));
247	        if (!is_valid_utf8(value)) value = latin1_to_utf8(value);
248	
249	        int current_set = X509_NAME_ENTRY_set(entry);
250	        if (i > 0) {
251	            out.append(current_set == previous_set ? "+" : ", ");
252	        }
253	        out.append(short_name);
254	        out.push_back('=');
255	        out.append(escape_dn_value(value));
256	        previous_set = current_set;
257	    }
258	    return true;
259	}
