261	bool encode_to_der(X509* cert, std::vector<unsigned char>& der) {
262	    int length = i2d_X509(cert, nullptr);
263	    if (length <= 0) return false;
264	    der.resize(static_cast<size_t>(length));
265	    unsigned char* pointer = der.data();
266	    int encoded = i2d_X509(cert, &pointer);
267	    return encoded == length &&
268	           pointer == der.data() + der.size();
269	}
