271	bool format_time(const ASN1_TIME* time, std::string& out) {
272	    struct tm tm_value {};
273	    if (ASN1_TIME_to_tm(time, &tm_value) != 1) return false;
274	    char buffer[32];
275	    int written = std::snprintf(
276	        buffer, sizeof(buffer), "%04d-%02d-%02dT%02d:%02d:%02dZ",
277	        tm_value.tm_year + 1900, tm_value.tm_mon + 1, tm_value.tm_mday,
278	        tm_value.tm_hour, tm_value.tm_min, tm_value.tm_sec);
279	    if (written <= 0 || static_cast<size_t>(written) >= sizeof(buffer)) {
280	        return false;
281	    }
282	    out.assign(buffer);
283	    return true;
284	}
