286	std::string format_fingerprint(const unsigned char* digest, size_t length) {
287	    std::string out;
288	    out.reserve(length * 3);
289	    for (size_t i = 0; i < length; ++i) {
290	        char byte_buffer[4];
291	        std::snprintf(byte_buffer, sizeof(byte_buffer), "%02X", digest[i]);
292	        if (i != 0) out.push_back(':');
293	        out.append(byte_buffer);
