298	// Reads the whole regular file into contents. Only a complete read that
299	// reaches end of file is a success: a directory, a non-regular file type, a
300	// partial read followed by an error, or any open/stat failure all return a
301	// read error message. errno is captured immediately after the failing call so
302	// the reason always belongs to this operation (never a stale "Success").
303	bool read_file_contents(const std::string& path, std::string& contents,
304	                        std::string& error) {
305	    int fd = open(path.c_str(), O_RDONLY);
306	    if (fd < 0) {
307	        int saved_errno = errno;
308	        error = std::strerror(saved_errno);
309	        return false;
310	    }
311	
312	    struct stat status {};
313	    if (fstat(fd, &status) != 0) {
314	        int saved_errno = errno;
315	        close(fd);
316	        error = std::strerror(saved_errno);
317	        return false;
318	    }
319	    if (S_ISDIR(status.st_mode)) {
320	        close(fd);
321	        error = "is a directory; a certificate file cannot be a directory";
322	        return false;
323	    }
324	
325	    contents.clear();
326	    if (status.st_size > 0) {
327	        contents.reserve(static_cast<size_t>(status.st_size));
328	    }
329	    char buffer[65536];
330	    while (true) {
331	        ssize_t bytes_read = read(fd, buffer, sizeof(buffer));
332	        if (bytes_read > 0) {
333	            contents.append(buffer, static_cast<size_t>(bytes_read));
334	        } else if (bytes_read == 0) {
335	            break;  // end of file reached after a complete read
336	        } else if (errno != EINTR) {
337	            int saved_errno = errno;
338	            close(fd);
339	            contents.clear();
340	            error = std::strerror(saved_errno);
341	            return false;
342	        }
343	    }
344	
345	    if (close(fd) != 0) {
346	        int saved_errno = errno;
347	        contents.clear();
348	        error = std::strerror(saved_errno);
349	        return false;
350	    }
351	    return true;
352	}
