354	int inspect_file(const std::string& path) {
355	    std::string content;
356	    std::string read_error;
357	    if (!read_file_contents(path, content, read_error)) {
358	        std::cerr << "trustpeek: failed to read file '" << path
359	                  << "': " << read_error << '\n';
360	        return 1;
361	    }
362	
363	    if (content.empty()) {
364	        std::cerr << "trustpeek: invalid certificate in '" << path
365	                  << "': empty file\n";
366	        return 1;
367	    }
368	
369	    // The encoding is decided by what actually parses, never by the file
370	    // extension and never by marker-like text inside the certificate itself
371	    // (a subject name may legitimately contain "-----BEGIN CERTIFICATE-----").
372	    //
373	    // A DER certificate starts with a SEQUENCE tag (0x30), which no PEM file
374	    // can start with, so the two formats cannot be confused: try DER first
375	    // and require the certificate to occupy the entire file.
376	    const auto* const der_begin =
377	        reinterpret_cast<const unsigned char*>(content.data());
378	    const auto* const der_end = der_begin + content.size();
379	    const unsigned char* pointer = der_begin;
380	
381	    X509Ptr cert(d2i_X509(nullptr, &pointer,
382	                          static_cast<long>(content.size())),
383	                 X509_free);
384	    bool is_pem = false;
385	
386	    if (cert) {
387	        if (pointer != der_end) {
388	            std::cerr << "trustpeek: invalid certificate in '" << path
389	                      << "': trailing bytes after DER certificate\n";
390	            return 1;
391	        }
392	    } else {
393	        BioPtr bio(BIO_new_mem_buf(content.data(),
394	                                  static_cast<int>(content.size())),
395	                   BIO_free_all);
396	        if (!bio) {
397	            std::cerr << "trustpeek: internal error while reading '" << path
398	                      << "'\n";
399	            return 1;
400	        }
401	        cert.reset(PEM_read_bio_X509(bio.get(), nullptr, nullptr, nullptr));
402	        if (!cert) {
403	            // The marker search below only picks the diagnostic wording;
404	            // acceptance is always decided by the parse results above.
405	            if (content.find(kPemBegin) != std::string::npos) {
406	                std::cerr << "trustpeek: invalid certificate in '" << path
407	                          << "': PEM certificate block is malformed or "
408	                             "truncated\n";
409	            } else {
410	                std::cerr << "trustpeek: invalid certificate in '" << path
411	                          << "': DER certificate is malformed or truncated\n";
412	            }
413	            return 1;
414	        }
415	        is_pem = true;
416	    }
417	
418	    std::vector<unsigned char> der;
419	    if (!encode_to_der(cert.get(), der)) {
420	        std::cerr << "trustpeek: invalid certificate in '" << path
421	                  << "': failed to re-encode certificate\n";
422	        return 1;
423	    }
424	
425	    if (is_pem && !validate_single_pem(content, der)) {
426	        std::cerr << "trustpeek: invalid certificate in '" << path
427	                  << "': expected exactly one PEM certificate block with no "
428	                     "other non-whitespace content\n";
429	        return 1;
430	    }
431	
432	    const char* encoding_name = is_pem ? "PEM" : "DER";
433	
434	    std::string subject;
435	    std::string issuer;
436	    std::string not_before;
437	    std::string not_after;
438	    if (!format_name(X509_get_subject_name(cert.get()), subject) ||
439	        !format_name(X509_get_issuer_name(cert.get()), issuer) ||
440	        !format_time(X509_get0_notBefore(cert.get()), not_before) ||
441	        !format_time(X509_get0_notAfter(cert.get()), not_after)) {
442	        std::cerr << "trustpeek: invalid certificate in '" << path
443	                  << "': failed to parse certificate fields\n";
444	        return 1;
445	    }
446	
447	    unsigned char digest[EVP_MAX_MD_SIZE];
448	    size_t digest_length = 0;
449	    if (EVP_Q_digest(nullptr, "SHA256", nullptr, der.data(), der.size(), digest,
450	                     &digest_length) != 1) {
451	        std::cerr << "trustpeek: internal error while hashing '" << path
452	                  << "'\n";
453	        return 1;
454	    }
455	
456	    std::ostringstream output;
457	    output << "Encoding: " << encoding_name << '\n'
458	           << "Subject: " << subject << '\n'
459	           << "Issuer: " << issuer << '\n'
460	           << "Not Before: " << not_before << '\n'
461	           << "Not After: " << not_after << '\n'
462	           << "SHA-256 Fingerprint: "
463	           << format_fingerprint(digest, digest_length) << '\n'
464	           << "Note: this output displays certificate information only; "
465	              "reading the file successfully does not verify the signature "
466	              "or establish trust.\n";
467	    std::cout << output.str();
468	    return 0;
469	}
