473	int main(int argc, char* argv[]) {
474	    if (argc == 2 && std::string_view(argv[1]) == "--version") {
475	        std::cout << "trustpeek 0.1.0\n";
476	        return 0;
477	    }
478	    if (argc == 3 && std::string_view(argv[1]) == "inspect") {
479	        return inspect_file(argv[2]);
480	    }
481	    print_usage();
482	    return 2;
483	}
